import{_ as i,a,o as t,Y as l}from"./chunks/framework.BFAekxW2.js";const g=JSON.parse('{"title":"VS1053b: Audio Transmission, FIFO, Clocking, and Buffer Details","description":"","frontmatter":{},"headers":[],"relativePath":"VS1053b_Audio_FIFO_Clocking_Buffer.md","filePath":"VS1053b_Audio_FIFO_Clocking_Buffer.md"}'),r={name:"VS1053b_Audio_FIFO_Clocking_Buffer.md"};function n(o,e,s,d,c,u){return t(),a("div",null,e[0]||(e[0]=[l('<h1 id="vs1053b-audio-transmission-fifo-clocking-and-buffer-details" tabindex="-1">VS1053b: Audio Transmission, FIFO, Clocking, and Buffer Details <a class="header-anchor" href="#vs1053b-audio-transmission-fifo-clocking-and-buffer-details" aria-label="Permalink to “VS1053b: Audio Transmission, FIFO, Clocking, and Buffer Details”">​</a></h1><h2 id="📦-audio-fifo-and-buffering" tabindex="-1">📦 Audio FIFO and Buffering <a class="header-anchor" href="#📦-audio-fifo-and-buffering" aria-label="Permalink to “📦 Audio FIFO and Buffering”">​</a></h2><ul><li><strong>FIFO Depth</strong>: The VS1053b includes a 2048-byte (1 KiB) stereo FIFO buffer for input data. This allows smooth streaming and decoding of audio data.</li><li><strong>Data Flow</strong>: <ul><li>Input data arrives through the SDI (Serial Data Interface) and is buffered into the FIFO.</li><li>Decoded samples are passed to a DAC FIFO.</li></ul></li><li><strong>DREQ Pin</strong>: <ul><li>DREQ indicates whether VS1053b is ready to receive more data.</li><li>When DREQ is high, the device can accept at least 32 bytes of SDI data or one SCI command.</li><li>When DREQ is low, the host must stop sending data until it rises again.</li><li>DREQ can also be read via <code>SCI_WRAMADDR</code> = <code>0xC012</code> and <code>SCI_WRAM</code>.</li></ul></li><li><strong>FIFO and SDI Transmission</strong>: <ul><li>You may burst-send up to 32 bytes of SDI without checking DREQ again.</li><li>It is recommended to send data in 32-byte chunks, and toggle <code>XDCS</code> every now and then to resynchronize.</li></ul></li><li><strong>FIFO Internal Use</strong>: <ul><li>Buffering ensures uninterrupted decoding even with some jitter in data arrival.</li></ul></li></ul><h2 id="⏱-input-clock-frequency-and-internal-clock" tabindex="-1">⏱ Input Clock Frequency and Internal Clock <a class="header-anchor" href="#⏱-input-clock-frequency-and-internal-clock" aria-label="Permalink to “⏱ Input Clock Frequency and Internal Clock”">​</a></h2><ul><li><strong>XTALI (Input Clock)</strong>: Nominally 12.288 MHz. Acceptable range is <strong>12 MHz to 13 MHz</strong>.</li><li><strong>Internal Clock Multiplier (PLL)</strong>: <ul><li>Controlled via <code>SCI_CLOCKF</code> register.</li><li>Internal clock (CLKI) = XTALI × multiplier.</li><li>Supported multipliers range from <strong>1.0× to 5.0×</strong>.</li><li>Default is <strong>1.0×</strong>, must be increased for real-time decoding of high-bitrate content (e.g., AAC with PS/SBR).</li></ul></li><li><strong>SCI_CLOCKF Register Format</strong>: <ul><li><code>SC_MULT[15:13]</code>: Clock multiplier (0 = ×1.0, 1 = ×2.0, …, 7 = ×5.0)</li><li><code>SC_ADD[12:11]</code>: Addition for dynamic clock scaling (e.g., WMA)</li><li><code>SC_FREQ[10:0]</code>: XTALI tuning: <code>(XTALI - 8000000) / 4000</code>.</li><li>Example: <code>SCI_CLOCKF = 0x8BE8</code> means: XTALI=12 MHz, multiplier=3.5× + 1.0× → 54 MHz internal clock.</li></ul></li><li><strong>Maximum Internal Clock (CLKI)</strong>: 55.3 MHz</li><li><strong>After setting SCI_CLOCKF</strong>, wait for <strong>DREQ to rise</strong> before sending further data.</li></ul><h2 id="📶-sm-clk-range-and-clock-dividers" tabindex="-1">📶 SM_CLK_RANGE and Clock Dividers <a class="header-anchor" href="#📶-sm-clk-range-and-clock-dividers" aria-label="Permalink to “📶 SM_CLK_RANGE and Clock Dividers”">​</a></h2><ul><li><strong>SM_CLK_RANGE</strong> is a bit in the <code>SCI_MODE</code> register.</li><li>If set, allows use of 24–26 MHz crystals by dividing XTALI by 2.</li><li>Use when using high-frequency crystals. For 24.576 MHz crystal: enable <code>SM_CLK_RANGE</code> to simulate 12.288 MHz operation.</li><li><strong>Must be set immediately after hardware reset</strong> if using 24–26 MHz.</li></ul><h2 id="🔃-spi-speed-and-dynamic-scaling" tabindex="-1">🔃 SPI Speed and Dynamic Scaling <a class="header-anchor" href="#🔃-spi-speed-and-dynamic-scaling" aria-label="Permalink to “🔃 SPI Speed and Dynamic Scaling”">​</a></h2><ul><li>SPI communication is influenced by internal clock (CLKI).</li><li>System starts with CLKI = XTALI (1.0×). Higher SPI speeds are permitted <strong>after</strong> clock is increased via <code>SCI_CLOCKF</code>.</li><li><strong>Maximum SPI input speed for SDI</strong> is <strong>7 MHz</strong> at default clock, scales up with CLKI.</li><li><strong>SCI speed</strong> is limited by combined timing of <code>tWL + tWH + tH = 6 × CLKI + 25 ns</code> → SCI reads max speed ~CLKI / 7.</li></ul><h2 id="🎧-audio-transmission-and-playback" tabindex="-1">🎧 Audio Transmission and Playback <a class="header-anchor" href="#🎧-audio-transmission-and-playback" aria-label="Permalink to “🎧 Audio Transmission and Playback”">​</a></h2><h3 id="playback-via-sdi" tabindex="-1">Playback via SDI <a class="header-anchor" href="#playback-via-sdi" aria-label="Permalink to “Playback via SDI”">​</a></h3><ul><li>Data is transmitted via the SDI bus.</li><li>Data should be streamed regularly and in small chunks.</li><li><strong>DREQ should be respected every 32 bytes.</strong></li></ul><h3 id="streaming-mode" tabindex="-1">Streaming Mode <a class="header-anchor" href="#streaming-mode" aria-label="Permalink to “Streaming Mode”">​</a></h3><ul><li>Set <code>SM_STREAM</code> bit in <code>SCI_MODE</code> to activate.</li><li>Ideal for webradio-style data streaming.</li><li>VS1053 adjusts playback rate by ±5% to avoid buffer underflow.</li><li>Requirements: <ul><li>Bitrate ≤ 160 kbps</li><li>CBR preferred, no VBR</li><li>Sample rate ≤ 48 kHz</li></ul></li><li>Accuracy: Less than ±0.5% error yields optimal playback.</li></ul><h3 id="pcm-streaming" tabindex="-1">PCM Streaming <a class="header-anchor" href="#pcm-streaming" aria-label="Permalink to “PCM Streaming”">​</a></h3><ul><li>Send WAV header (e.g., with length 0xFFFFFFFF) to enter continuous PCM mode.</li><li>Supports 8-bit or 16-bit, mono or stereo samples.</li><li>Sample rate defined in WAV header.</li><li>If header not sent, defaults to 44.1 kHz stereo.</li></ul><h2 id="🧮-dac-clock-and-resampling" tabindex="-1">🧮 DAC Clock and Resampling <a class="header-anchor" href="#🧮-dac-clock-and-resampling" aria-label="Permalink to “🧮 DAC Clock and Resampling”">​</a></h2><ul><li>DAC operates at fixed internal clock (XTALI / 2), e.g., 6.144 MHz when XTALI=12.288 MHz.</li><li>Final audio rate is interpolated to a <strong>common sample rate</strong> internally.</li><li>DAC is oversampled <strong>128×</strong>, final resolution is <strong>18 bits</strong>.</li><li>Zero-cross detection used for volume changes.</li></ul><h2 id="🔁-timer-module-and-fifo-synchronization" tabindex="-1">🔁 Timer Module and FIFO Synchronization <a class="header-anchor" href="#🔁-timer-module-and-fifo-synchronization" aria-label="Permalink to “🔁 Timer Module and FIFO Synchronization”">​</a></h2><ul><li>VS1053 has 2× 32-bit timers for general timing purposes.</li><li>Timers are driven from a clock divider of the master clock.</li><li>Useful for precise control of recording/playback durations.</li><li>Not typically needed for regular audio streaming.</li></ul><h2 id="📚-related-registers-summary" tabindex="-1">📚 Related Registers Summary <a class="header-anchor" href="#📚-related-registers-summary" aria-label="Permalink to “📚 Related Registers Summary”">​</a></h2><table tabindex="0"><thead><tr><th>Register</th><th>Function</th></tr></thead><tbody><tr><td>SCI_MODE</td><td>Mode flags (SM_STREAM, SM_CLK_RANGE)</td></tr><tr><td>SCI_CLOCKF</td><td>Clock multiplier and input freq</td></tr><tr><td>SCI_AUDATA</td><td>Sample rate, stereo/mono setting</td></tr><tr><td>SCI_WRAMADDR</td><td>Memory read/write address</td></tr><tr><td>SCI_WRAM</td><td>Memory data for WRAMADDR</td></tr><tr><td>DAC_FCTL</td><td>DAC control (sample rate, PLL freq)</td></tr><tr><td>DREQ</td><td>Data request pin (status feedback)</td></tr></tbody></table><hr><p>This document summarizes all audio transmission and timing details from the VS1053b datasheet.</p>',24)]))}const h=i(r,[["render",n]]);export{g as __pageData,h as default};
